arguments.command:
cat > /tmp/gh-askpass.sh <<'EOF'
#!/bin/sh
case "$1" in
  *Username*) echo "x-access-token" ;;
  *) echo "$GITHUB_TOKEN" ;;
esac
EOF
chmod +x /tmp/gh-askpass.sh && cd /tmp/ross-main && GIT_ASKPASS=/tmp/gh-askpass.sh GIT_TERMINAL_PROMPT=0 git push --dry-run origin HEAD:refs/heads/main 2>&1 | tail -5

cd /tmp && sed -i 's/^changed = \[\]$/created = []\nchanged = []/' /tmp/transcribe.py && cat > /tmp/new-episodes.json <<'EOF'
{
  "S04/E02": ["The One With the Tuesday Dinner", "Tuesday arrives, and at 2:14 Wendell walks into booth four for a dinner nobody cooked him in thirty years. Nellie takes the seventh chair while notice one waits face down beside the pie."]
}
EOF
python3 /tmp/transcribe.py /tmp/ross-main
